import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { isQuestion, stateOf, t } from '../util';

/*
 * The question page's side column. Its numbers are fields of the discussion
 * itself (helpdeskYes, helpdeskHelpful, helpdeskGuides), sent with the
 * discussion page and only there, so showing them costs no request; an answer
 * to "Did this solve it?" is saved on the discussion (Solved.answer).
 */

/** Scroll to an element of the question, below the header. */
function jump(selector) {
  const el = document.querySelector(selector);
  if (el) el.scrollIntoView({
    behavior: 'smooth',
    block: 'start'
  });
}

/** "On this question": the question, its accepted answer, the rest. */
export class Contents extends Component {
  view() {
    return m("nav", {
      className: "HelpDeskToc",
      "aria-labelledby": "helpdesk-toc"
    }, m("h2", {
      className: "HelpDeskSide-heading",
      id: "helpdesk-toc"
    }, t('toc.heading')), m("ul", null, this.links().map(([label, go]) => m("li", null, m("button", {
      type: "button",
      className: "HelpDeskToc-link",
      onclick: go
    }, label)))));
  }
  links() {
    const discussion = this.attrs.discussion;
    const question = isQuestion(discussion);
    const links = [[t('toc.question'), () => window.scrollTo({
      top: 0,
      behavior: 'smooth'
    })]];
    if (stateOf(discussion) === 'solved') links.push([t('toc.accepted'), () => jump(question ? '.AnswersPost--accepted' : '.helpdesk-accepted')]);
    if (question) {
      links.push([t('toc.answers'), () => jump('.Answers-bar')]);
    } else if ((discussion.commentCount() || 0) > 1) {
      links.push([t('toc.replies'), () => app.current.get('stream')?.goToNumber?.(2)]);
    }
    return links;
  }
}

/** "Did this solve it for you?", under a solved question only. */
export class Solved extends Component {
  saving = false;
  view() {
    const discussion = this.attrs.discussion;
    const yes = discussion.attribute('helpdeskYes');

    // The server sends the numbers only under an accepted answer.
    if (typeof yes !== 'number') return null;
    return m("section", {
      className: "HelpDeskSolved",
      "aria-labelledby": "helpdesk-solved"
    }, m("h2", {
      className: "HelpDeskSolved-question",
      id: "helpdesk-solved"
    }, t('solved.question')), this.answerView(discussion.attribute('helpdeskHelpful')), m("p", {
      className: "HelpDeskSolved-count"
    }, t('solved.count', {
      count: yes
    })));
  }
  answerView(mine) {
    if (mine === null || mine === undefined) {
      return m("div", {
        className: "HelpDeskSolved-buttons"
      }, m(Button, {
        className: "Button HelpDeskSolved-button",
        disabled: this.saving,
        onclick: () => this.answer(true)
      }, t('solved.yes')), m(Button, {
        className: "Button HelpDeskSolved-button",
        disabled: this.saving,
        onclick: () => this.answer(false)
      }, t('solved.no')));
    }
    return m("p", {
      className: "HelpDeskSolved-thanks",
      "aria-live": "polite"
    }, mine ? t('solved.thanks_yes') : t('solved.thanks_no'), ' ', m("button", {
      type: "button",
      className: "HelpDeskSolved-undo",
      disabled: this.saving,
      onclick: () => this.answer(null)
    }, t('solved.undo')));
  }

  /** Saved as a field of the discussion (PATCH /api/discussions/{id}); the reply refreshes the numbers. */
  answer(helpful) {
    if (!app.session.user) {
      app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
      return;
    }
    this.saving = true;
    this.attrs.discussion.save({
      helpdeskHelpful: helpful
    }).catch(() => {
      /* app.request has already shown the error alert */
    }).finally(() => {
      this.saving = false;
      m.redraw();
    });
  }
}

/** "From the knowledge base": up to three articles about the same thing. */
export class Guides extends Component {
  view() {
    const articles = this.attrs.discussion.attribute('helpdeskGuides');
    if (!articles?.length) return null;
    return m("section", {
      className: "HelpDeskGuides",
      "aria-labelledby": "helpdesk-guides"
    }, m("h2", {
      className: "HelpDeskSide-heading",
      id: "helpdesk-guides"
    }, t('kb.heading')), m("ul", null, articles.map(article => m("li", null, m(Link, {
      className: "HelpDeskGuides-link",
      href: article.url,
      external: true
    }, m(Icon, {
      name: "far fa-file-alt"
    }), m("span", null, article.title))))));
  }
}
flarum.reg.add('ernestdefoe-helpdesk', 'forum/components/QuestionAside', { Contents: Contents,Solved: Solved,Guides: Guides, });